import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image%20(112).DrLPSpGQ.png",g=JSON.parse('{"title":"Forgot Password","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/forgot-password.md","filePath":"getting-started/forgot-password.md"}'),o={name:"getting-started/forgot-password.md"};function r(l,e,p,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="forgot-password" tabindex="-1">Forgot Password <a class="header-anchor" href="#forgot-password" aria-label="Permalink to &quot;Forgot Password&quot;">​</a></h1><h2 id="tradeboard-password-reset-system" tabindex="-1">Tradeboard Password Reset System <a class="header-anchor" href="#tradeboard-password-reset-system" aria-label="Permalink to &quot;Tradeboard Password Reset System&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Tradeboard provides a comprehensive dual-mode password reset system that allows users to recover their accounts through either:</p><ol><li><strong>TOTP (Time-based One-Time Password)</strong> authentication</li><li><strong>Email verification</strong> (requires SMTP configuration)</li></ol><p>This system is designed with security best practices and provides fallback options for different scenarios.</p><h3 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h3><ul><li>System Architecture</li><li>Authentication Methods</li><li>Setup Requirements</li><li>User Flow</li><li>Configuration Guide</li><li>Security Features</li><li>Troubleshooting</li><li>API Endpoints</li><li>Rate Limiting</li></ul><h3 id="system-architecture" tabindex="-1">System Architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System Architecture&quot;">​</a></h3><p>The password reset system follows a secure token-based approach with multiple verification methods:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐    ┌──────────────────┐    ┌─────────────────┐</span></span>
<span class="line"><span>│   User Request  │    │  Method Selection │    │  Verification   │</span></span>
<span class="line"><span>│                 │───▶│                  │───▶│                 │</span></span>
<span class="line"><span>│ Enter Email     │    │ TOTP or Email    │    │ Code/Link Check │</span></span>
<span class="line"><span>└─────────────────┘    └──────────────────┘    └─────────────────┘</span></span>
<span class="line"><span>                                                          │</span></span>
<span class="line"><span>                       ┌─────────────────┐               │</span></span>
<span class="line"><span>                       │  Password Reset │◀──────────────┘</span></span>
<span class="line"><span>                       │                 │</span></span>
<span class="line"><span>                       │ New Password    │</span></span>
<span class="line"><span>                       └─────────────────┘</span></span></code></pre></div><h3 id="authentication-methods" tabindex="-1">Authentication Methods <a class="header-anchor" href="#authentication-methods" aria-label="Permalink to &quot;Authentication Methods&quot;">​</a></h3><h4 id="_1-totp-authentication-recommended" tabindex="-1">1. TOTP Authentication (Recommended) <a class="header-anchor" href="#_1-totp-authentication-recommended" aria-label="Permalink to &quot;1. TOTP Authentication (Recommended)&quot;">​</a></h4><p><strong>Advantages:</strong></p><ul><li>Works offline</li><li>No external dependencies</li><li>Immediate verification</li><li>Always available</li></ul><p><strong>Requirements:</strong></p><ul><li>User must have TOTP configured</li><li>Authenticator app (Google Authenticator, Authy, etc.)</li></ul><p><strong>Flow:</strong></p><ol><li>User enters email address</li><li>User selects &quot;TOTP Authentication&quot;</li><li>User enters TOTP code from authenticator app</li><li>System validates code and allows password reset</li></ol><h4 id="_2-email-verification" tabindex="-1">2. Email Verification <a class="header-anchor" href="#_2-email-verification" aria-label="Permalink to &quot;2. Email Verification&quot;">​</a></h4><p><strong>Advantages:</strong></p><ul><li>User-friendly</li><li>No additional app required</li><li>Secure email delivery</li></ul><p><strong>Requirements:</strong></p><ul><li>SMTP configuration must be completed</li><li>User has access to their email</li></ul><p><strong>Flow:</strong></p><ol><li>User enters email address</li><li>User selects &quot;Email Verification&quot;</li><li>System sends reset link to user&#39;s email</li><li>User clicks link and resets password</li></ol><h3 id="setup-requirements" tabindex="-1">Setup Requirements <a class="header-anchor" href="#setup-requirements" aria-label="Permalink to &quot;Setup Requirements&quot;">​</a></h3><h4 id="totp-setup-always-available" tabindex="-1">TOTP Setup (Always Available) <a class="header-anchor" href="#totp-setup-always-available" aria-label="Permalink to &quot;TOTP Setup (Always Available)&quot;">​</a></h4><p>TOTP is automatically configured during account creation. Each user gets:</p><ul><li>Unique TOTP secret key</li><li>QR code for easy setup</li><li>Backup secret for manual entry</li></ul><h4 id="smtp-configuration-required-for-email-reset" tabindex="-1">SMTP Configuration (Required for Email Reset) <a class="header-anchor" href="#smtp-configuration-required-for-email-reset" aria-label="Permalink to &quot;SMTP Configuration (Required for Email Reset)&quot;">​</a></h4><p><strong>Personal Gmail Configuration:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SMTP Server: smtp.gmail.com</span></span>
<span class="line"><span>Port: 587 (STARTTLS) or 465 (SSL/TLS)</span></span>
<span class="line"><span>Username: your-email@gmail.com</span></span>
<span class="line"><span>Password: [App Password - NOT regular password]</span></span>
<span class="line"><span>HELO Hostname: smtp.gmail.com</span></span>
<span class="line"><span>Use TLS: Yes</span></span></code></pre></div><p><strong>Gmail Workspace Configuration:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SMTP Server: smtp-relay.gmail.com</span></span>
<span class="line"><span>Port: 465 (SSL/TLS)</span></span>
<span class="line"><span>Username: your-email@yourdomain.com</span></span>
<span class="line"><span>Password: [App Password]</span></span>
<span class="line"><span>HELO Hostname: smtp.gmail.com</span></span>
<span class="line"><span>Use TLS: Yes</span></span></code></pre></div><p><strong>App Password Setup for Gmail:</strong></p><ol><li>Go to Google Account Settings</li><li>Navigate to Security → 2-Step Verification</li><li>Select &quot;App passwords&quot;</li><li>Generate a new app password for &quot;Mail&quot;</li><li>Use this password in SMTP configuration</li></ol><h3 id="user-flow" tabindex="-1">User Flow <a class="header-anchor" href="#user-flow" aria-label="Permalink to &quot;User Flow&quot;">​</a></h3><h4 id="password-reset-process" tabindex="-1">Password Reset Process <a class="header-anchor" href="#password-reset-process" aria-label="Permalink to &quot;Password Reset Process&quot;">​</a></h4><ol><li><strong>Initial Request</strong><ul><li>User visits <code>/auth/reset-password</code></li><li>Enters email address</li><li>System validates email format (client-side and server-side)</li></ul></li><li><strong>Method Selection</strong><ul><li>System presents two verification options: <ul><li>TOTP Authentication (always available)</li><li>Email Verification (if SMTP configured)</li></ul></li><li>User selects preferred method</li></ul></li><li><strong>TOTP Verification Path</strong><ul><li>User enters TOTP code from authenticator app</li><li>System validates code against user&#39;s TOTP secret</li><li>If valid, generates secure reset token</li><li>User proceeds to password reset form</li></ul></li><li><strong>Email Verification Path</strong><ul><li>System generates secure reset token</li><li>Sends password reset email with secure link</li><li>User clicks link in email</li><li>System validates token and shows password reset form</li></ul></li><li><strong>Password Reset</strong><ul><li>User enters new password</li><li>System validates password meets requirements: <ul><li>Minimum 8 characters</li><li>At least 1 uppercase letter (A-Z)</li><li>At least 1 lowercase letter (a-z)</li><li>At least 1 number (0-9)</li><li>At least 1 special character (@#$%^&amp;*)</li></ul></li><li>Password is hashed and stored securely</li><li>All reset tokens are invalidated</li></ul></li></ol><h3 id="configuration-guide" tabindex="-1">Configuration Guide <a class="header-anchor" href="#configuration-guide" aria-label="Permalink to &quot;Configuration Guide&quot;">​</a></h3><h4 id="smtp-configuration" tabindex="-1">SMTP Configuration <a class="header-anchor" href="#smtp-configuration" aria-label="Permalink to &quot;SMTP Configuration&quot;">​</a></h4><p>Access SMTP settings at <code>/auth/change</code> → &quot;SMTP Configuration&quot; tab:</p><ol><li><strong>Server Settings</strong><ul><li>Enter SMTP server hostname</li><li>Set appropriate port (587 for STARTTLS, 465 for SSL/TLS)</li><li>Configure HELO hostname</li></ul></li><li><strong>Authentication</strong><ul><li>Enter username (usually email address)</li><li>Enter App Password (not regular password for Gmail)</li><li>Set from email address</li></ul></li><li><strong>Security</strong><ul><li>Enable TLS/SSL encryption</li><li>Test configuration before saving</li></ul></li><li><strong>Testing</strong><ul><li>Use &quot;Send Test&quot; to verify configuration</li><li>Use &quot;Debug&quot; for detailed connection diagnostics</li></ul></li></ol><h4 id="totp-configuration" tabindex="-1">TOTP Configuration <a class="header-anchor" href="#totp-configuration" aria-label="Permalink to &quot;TOTP Configuration&quot;">​</a></h4><p>Access TOTP settings at <code>/auth/change</code> → &quot;TOTP Authentication&quot; tab:</p><ol><li><strong>QR Code Setup</strong><ul><li>Scan QR code with authenticator app</li><li>Or manually enter the secret key</li></ul></li><li><strong>Supported Apps</strong><ul><li>Google Authenticator</li><li>Authy</li><li>Microsoft Authenticator</li><li>1Password</li><li>Bitwarden</li></ul></li><li><strong>Backup</strong><ul><li>Save secret key in secure location</li><li>Test TOTP generation before relying on it</li></ul></li></ol><h3 id="security-features" tabindex="-1">Security Features <a class="header-anchor" href="#security-features" aria-label="Permalink to &quot;Security Features&quot;">​</a></h3><h4 id="token-security" tabindex="-1">Token Security <a class="header-anchor" href="#token-security" aria-label="Permalink to &quot;Token Security&quot;">​</a></h4><ul><li><strong>Cryptographically secure tokens</strong>: 32-byte URL-safe tokens</li><li><strong>Session-based validation</strong>: Tokens stored in server-side sessions</li><li><strong>Single-use tokens</strong>: Tokens invalidated after successful use</li><li><strong>Time-limited validity</strong>: Email tokens expire with session</li><li><strong>Secure transmission</strong>: HTTPS-only token delivery</li></ul><h4 id="anti-enumeration-protection" tabindex="-1">Anti-Enumeration Protection <a class="header-anchor" href="#anti-enumeration-protection" aria-label="Permalink to &quot;Anti-Enumeration Protection&quot;">​</a></h4><ul><li><strong>Consistent responses</strong>: Same response regardless of email existence</li><li><strong>Information leakage prevention</strong>: No indication if email is registered</li><li><strong>Rate limiting</strong>: Prevents brute force attacks</li></ul><h4 id="additional-security-measures" tabindex="-1">Additional Security Measures <a class="header-anchor" href="#additional-security-measures" aria-label="Permalink to &quot;Additional Security Measures&quot;">​</a></h4><ul><li><strong>CSRF protection</strong>: All forms protected with CSRF tokens</li><li><strong>Input validation</strong>: Email format and password strength validation</li><li><strong>Secure password hashing</strong>: Bcrypt with proper salt rounds</li><li><strong>Session security</strong>: Secure session cookie configuration</li></ul><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h4 id="common-smtp-issues" tabindex="-1">Common SMTP Issues <a class="header-anchor" href="#common-smtp-issues" aria-label="Permalink to &quot;Common SMTP Issues&quot;">​</a></h4><p><strong>Gmail Authentication Failed</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: SMTP Authentication failed</span></span>
<span class="line"><span>Solution: Use App Password instead of regular password</span></span>
<span class="line"><span>Steps: Google Account → Security → 2-Step Verification → App passwords</span></span></code></pre></div><p><strong>Gmail Workspace Relay Denied</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: Mail relay denied</span></span>
<span class="line"><span>Solution 1: Register server IP in Google Admin Console</span></span>
<span class="line"><span>Solution 2: Switch to personal Gmail settings (smtp.gmail.com:587)</span></span></code></pre></div><p><strong>Connection Timeout</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: Connection timeout</span></span>
<span class="line"><span>Check: Firewall blocking SMTP ports (587, 465)</span></span>
<span class="line"><span>Check: Network connectivity to SMTP server</span></span></code></pre></div><p><strong>SSL/TLS Errors</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: SSL handshake failed</span></span>
<span class="line"><span>Solution: Verify port configuration (587=STARTTLS, 465=SSL/TLS)</span></span>
<span class="line"><span>Check: Certificate validation settings</span></span></code></pre></div><h4 id="common-totp-issues" tabindex="-1">Common TOTP Issues <a class="header-anchor" href="#common-totp-issues" aria-label="Permalink to &quot;Common TOTP Issues&quot;">​</a></h4><p><strong>Invalid TOTP Code</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Issue: Code not accepted</span></span>
<span class="line"><span>Check: Time synchronization on device</span></span>
<span class="line"><span>Check: Code not expired (30-second window)</span></span>
<span class="line"><span>Solution: Manually sync time in authenticator app</span></span></code></pre></div><p><strong>Lost Authenticator Device</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Issue: Cannot generate TOTP codes</span></span>
<span class="line"><span>Solution: Use backup secret key to reconfigure</span></span>
<span class="line"><span>Fallback: Contact administrator for manual reset</span></span></code></pre></div><h4 id="email-delivery-issues" tabindex="-1">Email Delivery Issues <a class="header-anchor" href="#email-delivery-issues" aria-label="Permalink to &quot;Email Delivery Issues&quot;">​</a></h4><p><strong>Email Not Received</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check: Spam/junk folder</span></span>
<span class="line"><span>Check: Email address typos</span></span>
<span class="line"><span>Check: SMTP server logs</span></span>
<span class="line"><span>Verify: Test email functionality works</span></span></code></pre></div><p><strong>Reset Link Expired</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Issue: &quot;Invalid or expired reset link&quot;</span></span>
<span class="line"><span>Cause: Session expired or link already used</span></span>
<span class="line"><span>Solution: Request new password reset</span></span></code></pre></div><h3 id="locked-out-command-line-password-reset" tabindex="-1">Locked Out: Command-Line Password Reset <a class="header-anchor" href="#locked-out-command-line-password-reset" aria-label="Permalink to &quot;Locked Out: Command-Line Password Reset&quot;">​</a></h3><h4 id="try-this-first" tabindex="-1">Try this first <a class="header-anchor" href="#try-this-first" aria-label="Permalink to &quot;Try this first&quot;">​</a></h4><p>If you cannot log in and you have neither working SMTP nor an enrolled authenticator app, Tradeboard ships a command-line reset. It sets a new password without touching any of your data:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tradeboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/reset_admin_password.py</span></span></code></pre></div><p>Stop Tradeboard before running it. A live process caches the user row for 30 seconds and keeps accepting the old password until that expires.</p><p>Use <code>--list</code> to see the accounts on the install, and <code>--username</code> to pick one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/reset_admin_password.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/reset_admin_password.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourname</span></span></code></pre></div><p>If the script reports that stored secrets no longer decrypt, your <code>API_KEY_PEPPER</code> changed after the account was created. The reset still gets you logged in, but broker tokens, the stored API key and TOTP secrets were encrypted under the old pepper and cannot be recovered: log in to the broker again and regenerate the API key at <code>/apikey</code>. If you still have a backup of the original <code>.env</code>, restoring its <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code> lines recovers everything instead, including the old password.</p><h4 id="diagnose-the-database-first" tabindex="-1">Diagnose the database first <a class="header-anchor" href="#diagnose-the-database-first" aria-label="Permalink to &quot;Diagnose the database first&quot;">​</a></h4><p>If something looks wrong beyond the password itself, run the diagnostic. It is safe to run at any time and changes nothing that already exists:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/init_db.py</span></span></code></pre></div><p>It reports which database file the install is actually using, whether a relative <code>DATABASE_URL</code> plus an unexpected working directory has produced a second empty database, whether the tables and an account exist, and whether stored credentials still decrypt with the current <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code>. A pepper mismatch is the usual cause of &quot;Invalid credentials&quot; on a password you know is correct, and it is invisible from the login page.</p><p>Stop Tradeboard first. Historify is DuckDB and allows a single writer, so that one check reports a lock failure while the app is running.</p><h3 id="last-resort-complete-database-reset" tabindex="-1">Last Resort: Complete Database Reset <a class="header-anchor" href="#last-resort-complete-database-reset" aria-label="Permalink to &quot;Last Resort: Complete Database Reset&quot;">​</a></h3><h4 id="when-all-else-fails" tabindex="-1">When All Else Fails <a class="header-anchor" href="#when-all-else-fails" aria-label="Permalink to &quot;When All Else Fails&quot;">​</a></h4><p>Only if the command-line reset above cannot help (for example the database file itself is corrupt): <br><br> 1)stop tradeboard application <br> 2)Locate the file tradeboard.db from the db folder<br> 3)delete the tradeboard.db database file form the /db folder <br> 4)restart the tradeboard application<br> 5)Start signup with tradeboard fresh<br> 6)Ensure Gmail SMTP Settings or TOTP Authenticator is Configured</p><figure><img src="`+n+`" alt=""><figcaption></figcaption></figure><h4 id="what-you-will-lose" tabindex="-1">What You Will Lose <a class="header-anchor" href="#what-you-will-lose" aria-label="Permalink to &quot;What You Will Lose&quot;">​</a></h4><p><strong>WARNING: This action is irreversible and will permanently delete:</strong></p><ul><li><strong>User accounts and passwords</strong></li><li><strong>All trading logs and history</strong></li><li><strong>API access logs and analytics</strong></li><li><strong>Strategy configurations and backtests</strong></li><li><strong>SMTP/email settings</strong></li><li><strong>Rate limiting history</strong></li><li><strong>System settings and preferences</strong></li><li><strong>Custom configurations</strong></li></ul><h4 id="prevention-for-future" tabindex="-1">Prevention for Future <a class="header-anchor" href="#prevention-for-future" aria-label="Permalink to &quot;Prevention for Future&quot;">​</a></h4><p>To avoid needing database reset:</p><ol><li><strong>Save TOTP Secret Key</strong>: Store authenticator backup codes securely</li><li><strong>Configure SMTP Early</strong>: Set up email recovery before you need it</li><li><strong>Document Credentials</strong>: Keep encrypted record of important settings</li><li><strong>Regular Backups</strong>: Schedule automatic database backups</li><li><strong>Test Recovery</strong>: Periodically test password reset functionality</li></ol><h4 id="alternative-recovery-methods" tabindex="-1">Alternative Recovery Methods <a class="header-anchor" href="#alternative-recovery-methods" aria-label="Permalink to &quot;Alternative Recovery Methods&quot;">​</a></h4><p>Before resorting to database reset, try these:</p><ol><li><strong>Command-line reset</strong>: <code>uv run python upgrade/reset_admin_password.py</code> (see above). This is the supported path and should be your first move.</li><li><strong>Database diagnostic</strong>: <code>uv run python upgrade/init_db.py</code> reports whether the real problem is a pepper mismatch or the wrong database file.</li><li><strong>TOTP secret recovery</strong>: If you saved the original secret key, re-add it to your authenticator.</li><li><strong>Backup restoration</strong>: If you have a recent database backup, restore it along with the <code>.env</code> it was created with. The database and its <code>API_KEY_PEPPER</code> and <code>FERNET_SALT</code> must match.</li></ol><h3 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h3><p>The password reset system implements rate limiting to prevent abuse:</p><h4 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h4><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Login rate limits (applied to reset password as well)</span></span>
<span class="line"><span>LOGIN_RATE_LIMIT_MIN=5 per minute</span></span>
<span class="line"><span>LOGIN_RATE_LIMIT_HOUR=25 per hour</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Password reset specific limit</span></span>
<span class="line"><span>RESET_RATE_LIMIT=15 per hour</span></span></code></pre></div><h4 id="limits-applied" tabindex="-1">Limits Applied <a class="header-anchor" href="#limits-applied" aria-label="Permalink to &quot;Limits Applied&quot;">​</a></h4><ul><li><strong>Password reset requests</strong>: 15 per hour per IP</li><li><strong>SMTP test requests</strong>: Inherits from login limits</li><li><strong>Failed authentication attempts</strong>: Tracked separately</li></ul><h4 id="rate-limit-headers" tabindex="-1">Rate Limit Headers <a class="header-anchor" href="#rate-limit-headers" aria-label="Permalink to &quot;Rate Limit Headers&quot;">​</a></h4><p>When rate limited, responses include:</p><ul><li><code>X-RateLimit-Limit</code>: Maximum requests allowed</li><li><code>X-RateLimit-Remaining</code>: Requests remaining in window</li><li><code>X-RateLimit-Reset</code>: Time when limit resets</li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><h4 id="for-users" tabindex="-1">For Users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For Users&quot;">​</a></h4><ol><li><strong>TOTP Setup</strong>: Always configure TOTP as primary recovery method</li><li><strong>Backup Codes</strong>: Save TOTP secret key securely</li><li><strong>Email Security</strong>: Use secure email provider with 2FA</li><li><strong>Strong Passwords</strong>: Follow password requirements strictly</li></ol><h4 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h4>`,113)])])}const m=s(o,[["render",r]]);export{g as __pageData,m as default};
